/* CTI Briefs — in-page filter UI (vendored, integrity-checked).

   Wires up the tag / region chip filters and the section-visibility
   toggles on a brief page. The page is fully readable without this
   script — filtering is progressive enhancement. CSP-safe (no inline
   handlers; binds on DOMContentLoaded).

   Public surface: the script binds to whatever `[data-filter="brief"]`
   elements exist in the document. No globals.

   Tag / region semantics (matching standard expectations):
     - within a facet: OR across active chips
     - across facets: AND
     - no chips active: nothing is hidden

   Section toggles:
     - chip with data-target="<section-anchor>" toggles its `<section>`
       element's `.section-hidden` class on click.
     - aria-pressed flips with the visible state.

   No localStorage; state is per-page-load.
*/
(function () {
  "use strict";
  function ready(fn) {
    if (document.readyState !== "loading") fn();
    else document.addEventListener("DOMContentLoaded", fn);
  }
  function tokens(str) {
    if (!str) return [];
    return str.split(/\s+/).filter(Boolean);
  }
  function bindBrief(root) {
    var statusEl = root.querySelector('[data-role="filter-status"]');
    var clearBtn = root.querySelector('[data-action="clear-filters"]');
    var tagChips = root.querySelectorAll(".chip-tag");
    var regionChips = root.querySelectorAll(".chip-region");
    var sectionChips = root.querySelectorAll(".chip-section");
    var articles = document.querySelectorAll(".brief-item");
    var sections = document.querySelectorAll(".brief-section");

    function activeOf(chips, attr) {
      var out = [];
      chips.forEach(function (c) {
        if (c.getAttribute("aria-pressed") === "true") out.push(c.dataset[attr]);
      });
      return out;
    }

    function applyFilters() {
      var activeTags = activeOf(tagChips, "tag");
      var activeRegs = activeOf(regionChips, "region");
      var anyActive = activeTags.length > 0 || activeRegs.length > 0;
      var hidden = 0;
      articles.forEach(function (art) {
        var t = tokens(art.dataset.tags || "");
        var r = tokens(art.dataset.regions || "");
        var matchTag = activeTags.length === 0 || activeTags.some(function (x) { return t.indexOf(x) >= 0; });
        var matchReg = activeRegs.length === 0 || activeRegs.some(function (x) { return r.indexOf(x) >= 0; });
        var visible = matchTag && matchReg;
        art.classList.toggle("filter-hidden", !visible);
        if (!visible) hidden += 1;
      });
      // Section auto-hide: a section whose every article is filter-hidden
      // collapses to a small placeholder.
      sections.forEach(function (sec) {
        var arts = sec.querySelectorAll(".brief-item");
        if (!arts.length) {
          sec.classList.remove("filter-section-empty");
          return;
        }
        var allHidden = true;
        arts.forEach(function (a) { if (!a.classList.contains("filter-hidden")) allHidden = false; });
        sec.classList.toggle("filter-section-empty", allHidden && anyActive);
      });
      if (statusEl) {
        if (anyActive && hidden > 0) {
          statusEl.textContent = hidden + " item" + (hidden === 1 ? "" : "s") + " hidden by current filters.";
          statusEl.hidden = false;
        } else {
          statusEl.hidden = true;
        }
      }
      document.body.classList.toggle("filter-active", anyActive);
    }

    function toggleChip(c) {
      var v = c.getAttribute("aria-pressed") === "true" ? "false" : "true";
      c.setAttribute("aria-pressed", v);
    }
    // Tag and region chips default to NOT active (no filter on first paint).
    tagChips.forEach(function (c) {
      c.setAttribute("aria-pressed", "false");
      c.addEventListener("click", function () { toggleChip(c); applyFilters(); });
    });
    regionChips.forEach(function (c) {
      c.setAttribute("aria-pressed", "false");
      c.addEventListener("click", function () { toggleChip(c); applyFilters(); });
    });
    // Section chips default to ACTIVE (all sections visible). Click hides
    // the matching section.
    sectionChips.forEach(function (c) {
      c.addEventListener("click", function () {
        var id = c.dataset.target;
        if (!id) return;
        var sec = document.getElementById(id);
        if (!sec) return;
        var pressed = c.getAttribute("aria-pressed") === "true";
        var nextPressed = !pressed;
        c.setAttribute("aria-pressed", nextPressed ? "true" : "false");
        sec.classList.toggle("section-hidden", !nextPressed);
      });
    });
    if (clearBtn) {
      clearBtn.addEventListener("click", function () {
        tagChips.forEach(function (c) { c.setAttribute("aria-pressed", "false"); });
        regionChips.forEach(function (c) { c.setAttribute("aria-pressed", "false"); });
        sectionChips.forEach(function (c) {
          c.setAttribute("aria-pressed", "true");
          var id = c.dataset.target;
          if (id) {
            var sec = document.getElementById(id);
            if (sec) sec.classList.remove("section-hidden");
          }
        });
        applyFilters();
      });
    }
    applyFilters();
  }
  ready(function () {
    document.querySelectorAll('[data-filter="brief"]').forEach(bindBrief);
  });
})();
